ROOT = Path("/Users/runner/work/mobile-release-kit/mobile-release-kit")
HERE = ROOT / "fresh-validation"
PRODUCT_ROOT = ROOT / "prepared-built-source"
TRANSPORT_ROOT = ROOT / "_fresh-control-transport"
REPOSITORY = "Apdelrahman1911/mobile-release-kit"
WORKFLOW = ".github/workflows/macos-disposable-fresh.yml"
BRANCH = "codex/macos-fresh-validation"
TARGET = "aarch64-apple-darwin"


def need(value, reason):
    if not value:
        raise ValueError(reason)


def digest(body):
    return hashlib.sha256(body).hexdigest()


def pin(body, expected):
    need(type(expected) is dict and set(expected) == {"bytes", "sha256"}
         and type(expected["bytes"]) is int and len(body) == expected["bytes"]
         and digest(body) == expected["sha256"], "fixed-input-pin")
    return body


def scalar(value, size):
    return type(value) is str and re.fullmatch(r"[0-9a-f]{" + str(size) + "}", value) and value != "0" * size


def positive(value):
    return type(value) is str and re.fullmatch(r"[1-9][0-9]{0,19}", value)


def encode(value):
    return (json.dumps(value, sort_keys=True, separators=(",", ":")) + "\n").encode()


def hydration_environment(environment, prepared_binding, binding):
    """Product DATA for hydration; the actual workflow/run context stays intact."""
    manifest = prepared_binding.manifest
    need(prepared_binding.source == binding["productSource"]
         and manifest["inventorySha256"] == binding["inventorySha256"]
         and manifest["runtimeManifestSha256"] == binding["runtimeManifestSha256"],
         "prepared-hydration-anchors")
    return dict(environment, MRK_MACOS_INSTALL_SOURCE_COMMIT=prepared_binding.source,
        MRK_MACOS_INSTALL_INVENTORY_SHA256=manifest["inventorySha256"],
        MRK_BUNDLED_RUNTIME_MANIFEST_SHA256=manifest["runtimeManifestSha256"])


def bind_snapshot(template, run_binding, bounds):
    """Exactly two literal substitutions in the already pinned reader source."""
    need(type(template) is bytes and len(template) <= 64 * 1024
         and len(encode(run_binding)) <= 900 and type(bounds) is dict,
         "snapshot-binder-input")
    raw = template.decode("utf-8", "strict")
    for key, value in (("EXECUTION_BINDING", run_binding), ("SNAPSHOT_BOUNDS", bounds)):
        old = key + " = None\n"
        need(raw.count(old) == 1, "snapshot-one-literal-binding")
        raw = raw.replace(old, key + " = " + repr(value) + "\n")
    return raw.encode()


def host_data(binding, environment, *, machine, version, identity, flags, script):
    need(type(binding) is dict and binding.get("executionApproved") is True,
         "final-signed-input-binding-absent")
    need(script == HERE / "fresh_hosted_bootstrap.py" and machine == "arm64"
         and version.split(".")[0] == "26" and identity[0] == identity[1] != 0
         and identity[2] == identity[3] and flags == (True, True, True), "fixed-hosted-entry")
    job = environment.get("GITHUB_JOB")
    need(job in ("write-recovery", "torn-refusal"), "fixed-hosted-job")
    expected = {"GITHUB_ACTIONS": "true", "RUNNER_ENVIRONMENT": "github-hosted",
        "RUNNER_OS": "macOS", "RUNNER_ARCH": "ARM64", "GITHUB_REPOSITORY": REPOSITORY,
        "GITHUB_EVENT_NAME": "push", "GITHUB_WORKSPACE": str(ROOT),
        "GITHUB_SHA": binding["runnerSourceCommit"], "GITHUB_WORKFLOW_SHA": binding["runnerSourceCommit"],
        "GITHUB_REF": "refs/heads/" + binding["runnerBranch"],
        "GITHUB_WORKFLOW_REF": REPOSITORY + "/" + WORKFLOW + "@refs/heads/" + binding["runnerBranch"],
        "RUNNER_TEMP": "/Users/runner/work/_temp"}
    need(all(environment.get(k) == v for k, v in expected.items())
         and positive(environment.get("GITHUB_RUN_ID")) and positive(environment.get("GITHUB_RUN_ATTEMPT"))
         and binding["runnerBranch"] == BRANCH, "actual-runner-source-context")
    work = Path(environment.get("MRK_MACOS_WORK", ""))
    need(work.parent == Path(expected["RUNNER_TEMP"])
         and re.fullmatch(r"mrk-macos-installed\.[A-Za-z0-9]{8}", work.name), "fresh-fixed-work")
    return work, job


def first_module(path, expected, name):
    """Bootstrap only the hash-pinned E2 DATA module; no native entry is called."""
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        before = os.fstat(fd)
        need(stat.S_ISREG(before.st_mode) and before.st_nlink == 1
             and 0 < before.st_size <= 2 * 1024 * 1024, "bootstrap-module-bound")
        body = bytearray()
        while len(body) < before.st_size:
            part = os.read(fd, min(65536, before.st_size - len(body)))
            need(part, "bootstrap-short-source")
            body.extend(part)
        need(not os.read(fd, 1), "bootstrap-source-growth")
        def identity(value):
            return tuple(getattr(value, key) for key in ("st_dev", "st_ino", "st_mode", "st_uid", "st_gid", "st_nlink", "st_size", "st_mtime_ns", "st_ctime_ns"))
        need(identity(before) == identity(os.fstat(fd)) == identity(os.stat(path, follow_symlinks=False)), "bootstrap-source-post")
        body = pin(bytes(body), expected)
    finally:
        os.close(fd)
    module = ModuleType(name)
    module.__file__ = str(path)
    sys.modules[name] = module
    exec(compile(body, str(path), "exec"), module.__dict__)
    return module



def source_descriptor_quote(binding):
    """Exact source handles plus separate existing-owner and controller reserves."""
    pins = binding["sourceFiles"]
    need(type(pins) is dict and set(pins) == {"runner", "product"}, "fixed-source-roster")
    parents, count = set(), 0
    for scope, root in (("runner", ROOT), ("product", PRODUCT_ROOT)):
        group = pins[scope]
        need(type(group) is dict and 0 < len(group) <= 768, "fixed-source-roster")
        for relative in group:
            need(type(relative) is str and not relative.startswith("/")
                 and all(p not in ("", ".", "..") for p in relative.split("/")), "fixed-source-relative")
            parents.update((root / relative).parents)
        parents.update((root / ".git/HEAD").parents)
        count += len(group)
    sources = count + 2 + len(parents)
    # Prepared256 includes its216 retained originals and40 codec/capture slots.
    # Outer32 covers the concurrent E2 books; ambient16 covers the interpreter.
    return {"sourceFiles": count, "sourceHeads": 2, "sourceDirectories": len(parents),
        "sourceHandles": sources, "preparedReserve": 256, "outerReserve": 32,
        "ambientReserve": 16, "required": sources + 256 + 32 + 16,
        "controllerSoftTarget": 2048}


def source_descriptor_capacity(binding, resource_api):
    """Only this disposable controller's soft limit; hard and owner caps stay fixed."""
    quote = source_descriptor_quote(binding)
    target = quote["controllerSoftTarget"]
    need(quote["required"] <= target, "source-descriptor-quote-exceeds-controller-bound")
    before = resource_api.getrlimit(resource_api.RLIMIT_NOFILE)
    soft, hard = before
    need(hard == resource_api.RLIM_INFINITY or hard >= target,
         "source-descriptor-hard-capacity")
    change = soft != resource_api.RLIM_INFINITY and soft < target
    expected = (target, hard) if change else before
    if change:
        resource_api.setrlimit(resource_api.RLIMIT_NOFILE, expected)
    after = resource_api.getrlimit(resource_api.RLIMIT_NOFILE)
    need(after == expected and after[1] == hard
         and (after[0] == resource_api.RLIM_INFINITY or after[0] >= quote["required"]),
         "source-descriptor-actual-readback")
    return {"quote": quote, "before": {"soft": soft, "hard": hard},
        "after": {"soft": after[0], "hard": after[1]}, "softRaised": change,
        "hardChanged": False, "ownerBookLimitsChanged": False}


def admitted_sources(e2, binding):
    """Existing Originals holds the closed, reviewed import/data source roster."""
    book, bodies = e2.Originals(), {}
    try:
        pins = binding["sourceFiles"]
        need(set(pins) == {"runner", "product"}
             and sum(v["bytes"] for group in pins.values() for v in group.values()) <= 128 * 1024 * 1024,
             "source-aggregate-byte-bound")
        import resource
        capacity = source_descriptor_capacity(binding, resource)
        for scope, root in (("runner", ROOT), ("product", PRODUCT_ROOT)):
            pins = binding["sourceFiles"][scope]
            need(type(pins) is dict and 0 < len(pins) <= 768, "fixed-source-roster")
            for relative, expected in sorted(pins.items()):
                need(type(relative) is str and not relative.startswith("/")
                     and all(p not in ("", ".", "..") for p in relative.split("/")), "fixed-source-relative")
                _, body = book.file(root / relative, 4 * 1024 * 1024)
                bodies[(scope, relative)] = pin(body, expected)
            _, head = book.file(root / ".git/HEAD", 64)
            commit = binding["runnerSourceCommit"] if scope == "runner" else binding["productSource"]
            need(head == (commit + "\n").encode(), "actual-detached-source")
        book.check()
        need(len(book.entries) == capacity["quote"]["sourceHandles"], "actual-source-handle-count")
        return book, bodies, capacity
    except BaseException:
        book.finish()
        raise


def loaded_module(book, bodies, scope, relative, name):
    root = ROOT if scope == "runner" else PRODUCT_ROOT
    need((scope, relative) in bodies and name not in sys.modules, "fixed-source-module")
    spec = importlib.util.spec_from_loader(name, loader=None)
    module = importlib.util.module_from_spec(spec)
    module.__file__ = str(root / relative)
    sys.modules[name] = module
    book.check()
    exec(compile(bodies[(scope, relative)], module.__file__, "exec"), module.__dict__)
    book.check()
    return module


def cohort(book, root, expected, *, limit):
    """Exact admitted extracted file names, using the existing nofollow reader."""
    need(type(expected) is dict and 0 < len(expected) <= 16, "fixed-cohort-roster")
    expected_dirs = {""}
    for name in expected:
        need(not name.startswith("/") and all(p not in ("", ".", "..") for p in name.split("/")), "fixed-cohort-relative")
        expected_dirs.update("/".join(name.split("/")[:i]) for i in range(1, len(name.split("/"))))
    for name in sorted(expected_dirs):
        entry = book.directory(root / name)
        children = {p[len(name) + 1:] if name else p for p in set(expected) | expected_dirs
                    if p and (p.rsplit("/", 1)[0] if "/" in p else "") == name}
        need(set(os.listdir(entry["fd"])) == children, "fixed-cohort-tree")
    values = {}
    for name, expected_pin in sorted(expected.items()):
        _, body = book.file(root / name, limit)
        values[name] = pin(body, expected_pin)
    book.check()
    return values



def control_image_readback(book, stager, path, body):
    """Check bytes and Darwin metadata on the same retained no-follow original."""
    entry, reread = book.file(path, 16 * 1024 * 1024, modes=(0o555,))
    need(reread == body, "control-image-readback-metadata")
    stager.no_xattrs(entry["fd"])
    book.check_one(entry)

def prepared_input_files(stager, work, binding):
    # The packaging root is0755; input and all other descendants remain0555.
    files = stager.tree(work / "scripts", packager=True, mac_store_prefix="input/runtime/store")
    need({name for name in files if not name.startswith("input/")} == {"postinstall", "mrk-macos-install"},
         "prepared-script-root-roster")
    inputs = {name[len("input/"):]: item for name, item in files.items() if name.startswith("input/")}
    need(sum(len(item[0]) for item in inputs.values()) == binding["preparedInputFacts"]["inputFileBytes"],
         "prepared-input-file-bytes")
    return inputs

def python_framework_identity(info):
    return [getattr(info, 'st_' + key, 0) for key in
            ('dev', 'ino', 'mode', 'uid', 'gid', 'nlink', 'size', 'mtime_ns', 'ctime_ns', 'flags')]


def python_framework_policy_data(info, directory):
    mode = stat.S_IMODE(info.st_mode)
    need(info.st_uid == 0 and info.st_gid in (0, 80)
         and getattr(info, 'st_flags', 0) == 0, 'fixed-python-framework-owner-flags')
    need((stat.S_ISDIR(info.st_mode) and mode in (0o755, 0o775)) if directory else
         (stat.S_ISREG(info.st_mode) and mode in (0o555, 0o755, 0o775)
          and info.st_nlink == 1 and 0 < info.st_size <= 64 * 1024 * 1024),
         'fixed-python-framework-type-mode')


def admit_data_python(op, book, runner, binding, work):
    """Tighten only the provider-installed3.14 framework on this disposable VM.

    CPython's official installer deliberately uses admin-group0775 directories
    and group-writable files. Preserve the strict Originals policy by removing
    group/other write bits, never by accepting them. No chown, ACL/xattr edit,
    content write, signature change, fallback interpreter or owner-Mac action.
    """
    need(not getattr(op, 'fresh_python_admission_consumed', False), 'fixed-python-preparation-never-replayed')
    op.fresh_python_admission_consumed = True
    need(tuple(sys.version_info[:3]) == (3, 14, 7), 'fixed-data-python-version')
    python = Path(sys.executable).resolve(strict=True)
    framework = Path('/Library/Frameworks/Python.framework')
    version = framework / 'Versions/3.14'
    need(python in (version / 'bin/python3.14', version / 'Resources/Python.app/Contents/MacOS/Python'),
         'fixed-provider-python-framework-path')
    paths = [framework, framework / 'Versions', version]
    for parent in reversed(python.parent.parents):
        if version in parent.parents and parent not in paths:
            paths.append(parent)
    if python.parent not in paths:
        paths.append(python.parent)
    need(len(paths) <= 9, 'fixed-python-framework-depth')
    # Export actual narrow metadata even if a later owner/mode gate refuses.
    op.outputs.publish(work / 'fresh-python-parent-observation.json', encode(dict(
        python=str(python), version=list(sys.version_info[:3]),
        objects=[dict(path=str(p), identity=python_framework_identity(p.lstat()))
                 for p in [Path('/Library/Frameworks'), *paths, python]])))
    base = book.directory(Path('/Library/Frameworks'))
    opened = []; by_path = {Path('/Library/Frameworks'): base['fd']}
    close_errors = []
    flags = os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC
    try:
        for path in [*paths, python]:
            directory = path != python
            parent_fd = by_path[path.parent]
            fd = os.open(path.name, flags | (os.O_DIRECTORY if directory else 0), dir_fd=parent_fd)
            row = dict(path=path, fd=fd, parent=parent_fd, before=None)
            opened.append(row)
            before = os.fstat(fd); python_framework_policy_data(before, directory)
            row['before'] = python_framework_identity(before)
            need(row['before'] == python_framework_identity(os.stat(path.name, dir_fd=parent_fd, follow_symlinks=False)),
                 'fixed-python-framework-named-original')
            if directory: by_path[path] = fd
        def binary_hash():
            row = opened[-1]; size = row['before'][6]; h = hashlib.sha256(); offset = 0
            while offset < size:
                block = os.pread(row['fd'], min(65536, size - offset), offset)
                need(bool(block), 'fixed-python-framework-short-read'); h.update(block); offset += len(block)
            need(not os.pread(row['fd'], 1, size), 'fixed-python-framework-grew')
            return h.hexdigest()
        before_hash = binary_hash()
        for row in opened:
            need(row['before'] == python_framework_identity(os.fstat(row['fd'])) ==
                 python_framework_identity(os.stat(row['path'].name, dir_fd=row['parent'], follow_symlinks=False)),
                 'fixed-python-framework-pre-original')
        op.outputs.publish(work / 'fresh-python-hardening-before.json', encode(dict(
            kind='disposable-provider-python-mode-only-before', python=str(python), binarySha256=before_hash,
            objects=[dict(path=str(row['path']), identity=row['before']) for row in opened],
            recursiveScope=str(version), symlinksFollowed=False, ownerMachineEffects=False)))
        commands = (
            ('python-framework-ancestors', ['/usr/bin/sudo', '-n', '--', '/bin/chmod', '-h', 'go-w',
                str(framework), str(framework / 'Versions')]),
            ('python-framework-version', ['/usr/bin/sudo', '-n', '--', '/bin/chmod', '-R', '-P', 'go-w', str(version)]),
        )
        for label, argv in commands:
            runner.original_call(op, label, argv, binding['commandEnvironment'], cwd=work, timeout=60, limit=65536, zero=True)
        after_rows = []
        for row in opened:
            after = python_framework_identity(os.fstat(row['fd']))
            need(after == python_framework_identity(os.stat(row['path'].name, dir_fd=row['parent'], follow_symlinks=False)),
                 'fixed-python-framework-post-named')
            before = row['before']
            need(after[2] == before[2] & ~0o022 and all(after[i] == before[i] for i in (0, 1, 3, 4, 5, 6, 7, 9)),
                 'fixed-python-framework-mode-only-post')
            after_rows.append(dict(path=str(row['path']), identity=after))
        need(binary_hash() == before_hash, 'fixed-python-framework-content-changed')
        # The unmodified strict reader must now accept every actual ancestor
        # and the interpreter. The chmod result alone never establishes this.
        book.file(python, 64 * 1024 * 1024, uid=0, modes=(0o555, 0o755))
        op.outputs.publish(work / 'fresh-python-hardening-after.json', encode(dict(
            kind='disposable-provider-python-mode-only-after', python=str(python), binarySha256=before_hash,
            objects=after_rows, strictOriginalsAdmissionPassed=True, modeOnly=True,
            fixedOriginalsReturnedZero=True, originalClosesStillPending=True, ownerMachineEffects=False)))
    finally:
        for row in reversed(opened):
            fd, row['fd'] = row['fd'], None
            try: os.close(fd)
            except OSError: close_errors.append(str(row['path']))
        need(not close_errors, 'fixed-python-framework-close-unknown')
    op.outputs.publish(work / 'fresh-python-hardening-closed.json', encode(dict(
        kind='disposable-provider-python-originals-closed', closed=len(opened), originalClosesKnown=True)))
    return python


def main():
    # Refuse before native probes, metadata calls, or any protected path read.
    need(EXECUTION_BINDING is not None, "final-signed-input-binding-absent")
    binding = dict(EXECUTION_BINDING)
    need(sys.argv[1:] == [] and sys.platform == "darwin", "fixed-bootstrap-arguments")
    environment = dict(os.environ)
    # Actions authenticates this workflow checkout. Its own commit cannot be
    # embedded in its own bytes; preserve the actual source, never the product.
    need(scalar(environment.get("GITHUB_SHA"), 40)
         and environment.get("GITHUB_SHA") == environment.get("GITHUB_WORKFLOW_SHA"), "actual-workflow-source")
    binding["runnerSourceCommit"] = environment["GITHUB_SHA"]
    work, job = host_data(binding, environment, machine=platform.machine(), version=platform.mac_ver()[0],
        identity=(os.getuid(), os.geteuid(), os.getgid(), os.getegid()),
        flags=(bool(sys.flags.isolated), bool(sys.flags.no_site), bool(sys.dont_write_bytecode)),
        script=Path(__file__).absolute())
    e2 = first_module(ROOT / "desktop/tools/macos_e2_native_fixture.py",
        binding["sourceFiles"]["runner"]["desktop/tools/macos_e2_native_fixture.py"], "_fresh_existing_e2")
    book, bodies, descriptor_capacity = admitted_sources(e2, binding)
    op = None
    try:
        # Normal package modules import their canonical prepared module. Its
        # complete source is already held before this controlled path is added.
        sys.path.insert(0, str(ROOT))
        from desktop.tools import macos_prepared_package as prepared
        from desktop.tools import macos_android_helper_package as helper
        for module in (prepared, helper):
            relative = str(Path(module.__file__).relative_to(ROOT))
            need(("runner", relative) in bodies, "canonical-helper-source-roster")
        runner = loaded_module(book, bodies, "runner", "fresh-validation/fresh_hosted_runner.py", "_fresh_runner")
        bounds = loaded_module(book, bodies, "runner", "fresh-validation/fresh_snapshot_bounds.py", "_fresh_bounds")
        qualification = loaded_module(book, bodies, "runner", "desktop/tools/macos_aqua_qualification.py", "_fresh_owner_loader")
        need(all(("runner", "src/mobile_release/" + p) in bodies for p in qualification.OWNER_FILES), "existing-owner-source-roster")
        owner = qualification.load_owner(ROOT)
        runner_stager = loaded_module(book, bodies, "runner", "desktop/tools/stage_macos_installed.py", "_fresh_runner_stager")
        stager = loaded_module(book, bodies, "product", "desktop/tools/stage_macos_installed.py", "_fresh_product_stager")
        host = loaded_module(book, bodies, "runner", "desktop/tools/macos_xcode_host_preparation.py", "_fresh_host")
        resource_data = loaded_module(book, bodies, "runner", "desktop/tools/macos_fixed_carrier_resume.py", "_fresh_resource_data")
        op = e2.Operation(owner, SimpleNamespace(book=book), stager, work, environment)
        op.fresh_deadline = time.monotonic_ns() + 3600 * 1_000_000_000
        op.outputs.publish(work / "fresh-source-descriptor-capacity.json", encode(descriptor_capacity))
        runner.EXECUTION_BINDING = binding
        for name in ("fresh-home", "fresh-tmp"):
            op.mkdir(work / name)
        command_environment = {"PATH": "/usr/bin:/bin:/usr/sbin:/sbin", "LANG": "C", "LC_ALL": "C", "TZ": "UTC",
            "HOME": str(work / "fresh-home"), "TMPDIR": str(work / "fresh-tmp")}
        binding["commandEnvironment"] = command_environment
        host_api = host.DarwinAPI(runner.GroupClock(op), target=TARGET, expected_major=26)
        for scope, root, expected_tree in (("runner", ROOT, None),
            ("product", PRODUCT_ROOT, binding["productTree"]), ("controls", TRANSPORT_ROOT, binding["controlTransportTree"])):
            result = runner.original_call(op, "source-tree-" + scope,
                ["/usr/bin/git", "--no-optional-locks", "rev-parse", "HEAD^{tree}"], command_environment,
                cwd=root, timeout=10, limit=4096, zero=True)
            need(not result.stderr and len(result.stdout) == 41 and result.stdout.endswith(b"\n")
                 and scalar(result.stdout[:-1].decode("ascii"), 40), "actual-source-tree")
            if scope == "runner":
                binding["runnerSourceTree"] = result.stdout[:-1].decode("ascii")
            else:
                need(result.stdout == (expected_tree + "\n").encode(), "bound-source-tree")
        # Existing protected host prerequisite is a workflow prerequisite;
        # this reader checks its actual result before any package/cut work.
        op.protected.directory(Path("/Applications"))
        consumer = dict(source=environment["GITHUB_SHA"], tree=binding["runnerSourceTree"], target=TARGET,
            runId=environment["GITHUB_RUN_ID"], runAttempt=environment["GITHUB_RUN_ATTEMPT"])
        acquisition = helper.Operation(owner, ROOT, work, "package-install", environment, runner_stager, target=TARGET)
        values, prepared_binding = prepared.acquire_checkpoint(acquisition, consumer)
        need(prepared_binding.origin == binding["preparedOrigin"] and prepared_binding.source == binding["productSource"], "exact-prepared-origin")
        for name, expected in binding["preparedMembers"].items():
            pin(values[name], expected)
        need(set(values) == set(binding["preparedMembers"]), "exact-prepared-cohort")
        product_environment = hydration_environment(environment, prepared_binding, binding)
        hydration = helper.Operation(owner, PRODUCT_ROOT, work, "package-install", product_environment, stager,
            target=TARGET, prepared=prepared_binding)
        prepared.hydrate_checkpoint(hydration, values, prepared_binding)
        op.outputs.publish(work / "prepared-bootstrap-originals.json", encode({"acquisition": acquisition.receipt,
            "hydration": hydration.receipt, "preparedOrigin": prepared_binding.origin, "actualConsumer": consumer}))
        carrier = cohort(book, work / "ordinary-carrier", binding["carrierMembers"], limit=4 * 1024 * 1024)
        carrier_record = prepared.ordinary_local_carrier_transport_data(
            {k: carrier[k] for k in prepared.LOCAL_CARRIER_FILES}, binding["carrierConsumer"])
        need(prepared.decode(carrier["LOCAL-CARRIER.json"], 16384) == carrier_record,
             "existing-six-member-carrier-record")
        need(carrier_record["producer"] == prepared_binding.origin and carrier_record["packageSha256"] == binding["package"]["sha256"], "same-prepared-carrier-product")
        _, package = book.file(work / "package-final/MobileReleaseKit.pkg", 512 * 1024 * 1024)
        pin(package, binding["package"])
        producer, signature = carrier["producer-root/producer.json"], carrier["producer-root/producer.sig"]
        pin(producer, binding["producer"]); pin(signature, binding["signature"])
        input_files = prepared_input_files(stager, work, binding)
        inventory = input_files[stager.INSTALLATION_INVENTORY_NAME][0]
        need(digest(inventory) == binding["inventorySha256"]
             and prepared_binding.manifest["runtimeManifestSha256"] == binding["runtimeManifestSha256"], "hydrated-input-anchors")
        quote = bounds.derive_inventory(inventory, len(bodies[("runner", "fresh-validation/darwin_metadata.py")]))
        need(quote == binding["snapshotQuote"], "final-inventory-derived-quote")
        transport = cohort(book, TRANSPORT_ROOT / "fresh-controls", binding["transportMembers"], limit=16 * 1024 * 1024)
        _, transport_head = book.file(TRANSPORT_ROOT / ".git/HEAD", 64)
        need(transport_head == (binding["controlTransportCommit"] + "\n").encode(), "actual-control-transport-head")
        manifest = runner.document(transport["control-manifest.json"], 65536)
        need(digest(transport["control-manifest.json"]) == binding["controlTransportManifestSha256"]
             and manifest["productSource"] == binding["productSource"]
             and manifest["controlSourceSha256"] == binding["controlSourceSha256"]
             and manifest["controlManifestSha256"] == binding["controlManifestSha256"], "control-transport-source")
        control_bodies = {}
        for role in ("census", "write", "torn"):
            body = transport[role + "/mrk-macos-install"]
            expected = binding["controls"][role]
            need(all(manifest["controls"][role][k] == expected[k] for k in ("path", "bytes", "sha256"))
                 and manifest["controls"][role]["compilerOriginalClosureKnown"] is True
                 and manifest["controls"][role]["compilerOriginalReturn"] == 0, "exact-control-compiler-original")
            pin(body, {k: expected[k] for k in ("bytes", "sha256")})
            stager.macho(body, system_only=True, target=TARGET)
            directory = work / ("fresh-control-" + role)
            op.mkdir(directory)
            path = directory / "mrk-macos-install"
            op.outputs.publish(path, body, 0o555)
            for label, argv in (("verify", ["--verify", "--strict", "--all-architectures"]),
                                ("display", ["--display", "--verbose=4"])):
                result = runner.original_call(op, "control-" + role + "-" + label,
                    ["/usr/bin/codesign", *argv, str(path)], binding["commandEnvironment"], cwd=work,
                    timeout=10, limit=65536, zero=True)
                if label == "display":
                    lines = (result.stdout + result.stderr).splitlines()
                    need(lines.count(b"Signature=adhoc") == 1, "unchanged-compiler-adhoc-image")
            control_image_readback(book, stager, path, body)
            control_bodies[role] = body
        root_environment = {"PATH": "/usr/bin:/bin:/usr/sbin:/sbin", "LANG": "C", "LC_ALL": "C", "TZ": "UTC",
            **{k: environment[k] for k in ("GITHUB_ACTIONS", "RUNNER_ENVIRONMENT", "RUNNER_OS", "RUNNER_ARCH",
                "GITHUB_REPOSITORY", "GITHUB_SHA", "GITHUB_RUN_ID", "GITHUB_RUN_ATTEMPT", "GITHUB_JOB")}}
        snapshot_binding = {k: root_environment[k] for k in ("GITHUB_REPOSITORY", "GITHUB_SHA", "GITHUB_RUN_ID", "GITHUB_RUN_ATTEMPT", "GITHUB_JOB")}
        snapshot_dir = work / "fresh-snapshot"
        op.mkdir(snapshot_dir)
        template = bodies[("runner", "fresh-validation/read_torn_tree.py")]
        bound_reader = bind_snapshot(template, snapshot_binding, quote["bounds"])
        op.outputs.publish(snapshot_dir / "read_torn_tree.py", bound_reader, 0o444)
        op.outputs.publish(snapshot_dir / "darwin_metadata.py", bodies[("runner", "fresh-validation/darwin_metadata.py")], 0o444)
        for name in ("read_torn_tree.py", "darwin_metadata.py"):
            book.file(snapshot_dir / name, 65536, modes=(0o444,))
        python = admit_data_python(op, book, runner, binding, work)
        scripts = {name: bodies[("runner", "fresh-validation/scripts/" + name)] for name in
                   ("cut-postinstall", "frontier-postinstall", "completed-postinstall")}
        need(set(binding["scriptPins"]) == set(scripts), "exact-control-script-roster")
        for name, body in scripts.items(): pin(body, binding["scriptPins"][name])
        actual = dict(binding, job=job, runId=environment["GITHUB_RUN_ID"], runAttempt=environment["GITHUB_RUN_ATTEMPT"],
            jobId=job, inputPath=work / "input", storeRuntime=True, inputFiles=input_files, packageBody=package,
            producerBody=producer, signatureBody=signature, controlBodies=control_bodies, scriptBodies=scripts,
            resourceModule=resource_data, snapshotBinding=snapshot_binding, rootSnapshotEnvironment=root_environment,
            dataPython=str(python), runnerSource=snapshot_dir, sourceBytes=sum(map(len, bodies.values())),
            e2Module=e2, hostAPI=host_api)
        # Fresh requested-name identity is nominated once from the actual job.
        actual["ordinaryRequestId"] = digest(encode({"run": actual["runId"], "attempt": actual["runAttempt"],
            "job": job, "package": binding["package"]["sha256"]}))[:32]
        op.outputs.publish(work / "fresh-bootstrap-binding.json", encode({
            "productSource": binding["productSource"], "runnerSource": binding["runnerSourceCommit"],
            "controlTransportCommit": binding["controlTransportCommit"], "actualConsumer": consumer,
            "job": job, "snapshotTemplateSha256": digest(template), "boundSnapshotSha256": digest(bound_reader),
            "snapshotBinding": snapshot_binding, "snapshotQuote": quote,
            "producerPairRegenerated": False, "controlImagesSignedOrExecuted": False}))
        receipt = runner.settle_job(op, stager, host_api, actual)
        sys.stdout.buffer.write(encode(receipt)); sys.stdout.buffer.flush()
        return 0 if receipt["passed"] else 1
    finally:
        if op is None:
            need(book.finish(), "bootstrap-source-close-unknown")
        else:
            # Safe idempotent close consumption only, never an installed cleanup.
            results = [b.finish() for b in (op.outputs, op.protected, book)]
            need(all(results), "bootstrap-original-close-unknown")


if __name__ == "__main__":
    raise SystemExit(main())
